<?php
declare(strict_types=1);
use Vendi\Database\Connection;
require dirname(__DIR__).'/vendor/autoload.php';
$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);$token=preg_replace('/[^a-f0-9]/i','',(string)($_GET['t']??''));$q=$db->prepare("SELECT s.id,s.total,i.id invoice_id,i.status invoice_status FROM sales s LEFT JOIN invoices i ON i.sale_id=s.id WHERE s.public_token=? LIMIT 1");$q->execute([$token]);$s=$q->fetch();if(!$s){http_response_code(404);exit('Venta no encontrada');}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Facturar compra | Vendi</title><style>body{font-family:system-ui;background:#f5f7fb;color:#172033;margin:0}.w{max-width:620px;margin:auto;padding:24px}.c{background:#fff;padding:24px;border-radius:18px;border:1px solid #e5e7eb}label{display:block;margin:13px 0 5px;font-weight:650}input,select{width:100%;padding:12px;border:1px solid #ccd2dc;border-radius:10px;font-size:16px;box-sizing:border-box}button{width:100%;padding:14px;margin-top:18px;border:0;border-radius:11px;background:#176b47;color:#fff;font-weight:800}.note{color:#667085;font-size:13px}</style></head><body><main class="w"><section class="c"><h1>Facturar ticket #<?=$s['id']?></h1><p>Total: <b>$<?=number_format((float)$s['total'],2)?></b></p><?php if($s['invoice_id']):?><p>Esta venta ya tiene una solicitud de factura. Estado: <b><?=htmlspecialchars($s['invoice_status'])?></b>.</p><?php else:?><form method="post" action="api/public/invoice.php"><input type="hidden" name="token" value="<?=htmlspecialchars($token)?>"><label>RFC</label><input name="rfc" maxlength="13" required><label>Razón social / nombre fiscal</label><input name="tax_name" required><label>Código postal fiscal</label><input name="tax_zip" maxlength="10" required><label>Régimen fiscal</label><input name="tax_regime" required><label>Uso CFDI</label><input name="cfdi_use" required><label>Correo para recibir factura</label><input type="email" name="email" required><button>Solicitar factura</button></form><p class="note">El timbrado estará disponible cuando el negocio tenga un PAC configurado.</p><?php endif;?></section></main></body></html>